-- 007_employee_extra.sql + employee seed
-- Adds 3 new columns to employees + seeds 116 employees from Excel
-- Idempotent — safe to re-run


-- 1) Add new columns to employees table (idempotent)
DROP PROCEDURE IF EXISTS add_col_if_missing;
DELIMITER $$
CREATE PROCEDURE add_col_if_missing(IN tbl VARCHAR(64), IN col VARCHAR(64), IN ddl VARCHAR(500))
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = tbl AND COLUMN_NAME = col) THEN
    SET @s = CONCAT('ALTER TABLE `', tbl, '` ADD COLUMN ', ddl);
    PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;
  END IF;
END$$
DELIMITER ;

CALL add_col_if_missing('employees', 'manual_salary',          "manual_salary DECIMAL(18,3) NOT NULL DEFAULT 0 AFTER basic_salary");
CALL add_col_if_missing('employees', 'work_permit_salary',     "work_permit_salary DECIMAL(18,3) NOT NULL DEFAULT 0 AFTER manual_salary");
CALL add_col_if_missing('employees', 'last_leave_return_date', "last_leave_return_date DATE NULL AFTER residency_expiry");
DROP PROCEDURE IF EXISTS add_col_if_missing;


