-- 4) Remove existing placeholder employee EMP-0001 (and any related rows)

SET @old_emp = (SELECT id FROM employees WHERE employee_no = 'EMP-0001' LIMIT 1);
DELETE FROM leave_requests       WHERE employee_id = @old_emp;
DELETE FROM employee_requests    WHERE employee_id = @old_emp;
DELETE FROM employee_salary_components WHERE employee_id = @old_emp;
DELETE FROM payslip_lines WHERE payslip_id IN (SELECT id FROM payslips WHERE employee_id = @old_emp);
DELETE FROM payslips             WHERE employee_id = @old_emp;
DELETE FROM overtime_entries     WHERE employee_id = @old_emp;
DELETE FROM employees            WHERE id = @old_emp;


